/**
 * GET /api/documents — the generated PDFs this caller is entitled to.
 *
 * Spec: `Official Documentation/13 Document and PDF System/STORAGE.md`
 *       `Official Documentation/13 Document and PDF System/PDF_GENERATION.md`
 *
 * ## Why this route exists
 *
 * `GET /api/documents/[id]` has issued signed URLs since it was written, and until
 * 2026-10-05 **no screen called it** — because nothing could find a document's id. A
 * receipt was generated by the worker, stored in R2 and recorded here, and the parent
 * fees screen showed the receipt NUMBER with nothing to click. Work that is correct and
 * unreachable, which is the most expensive failure this project keeps producing.
 *
 * So this is the lookup: given a payment, a pupil, or nothing at all, which documents
 * exist and are they ready.
 *
 * ## Entitlement stays in the policies
 *
 * Performed as the caller. `generated_documents` carries three SELECT policies —
 * AfriTech, the school's own staff, and a pupil's linked parents — so the rows that come
 * back are the rows this caller may have, and a parent asking for another family's
 * receipt gets an empty list rather than a refusal that confirms it exists.
 *
 * No service-role read, and no `schoolId` parameter. Accepting one would move the
 * decision out of the policies and into this file.
 *
 * ## It does not sign anything
 *
 * A list of twenty receipts would mean twenty signed URLs, nineteen of which expire
 * unused, and every one a live link to a child's name and an amount. The id is enough
 * for a screen to draw a button; `/[id]` signs one when it is actually clicked.
 */

import { z } from 'zod'

import { createUserClient } from '../../../lib/supabase'
import { fail, fromPostgrestError, guard, ok } from '../../../lib/api-response'

export const dynamic = 'force-dynamic'

/**
 * The CHECK on `generated_documents.doc_type`, mirrored.
 *
 * Kept as a literal union rather than a free string so a typo returns a validation
 * error here instead of an empty list that reads as "no receipt was ever produced".
 */
const DOC_TYPES = [
  'payment_receipt',
  'fee_statement',
  'report_card',
  'attendance_certificate',
  'transfer_letter',
] as const

const querySchema = z.object({
  paymentId: z.string().uuid().optional(),
  studentId: z.string().uuid().optional(),
  docType: z.enum(DOC_TYPES).optional(),
  academicYear: z.string().trim().max(9).optional(),
  termNumber: z.coerce.number().int().min(1).max(4).optional(),
  limit: z.coerce.number().int().min(1).max(100).default(50),
})

export async function GET(request: Request): Promise<Response> {
  return guard(async () => {
    const url = new URL(request.url)
    const parsed = querySchema.safeParse({
      paymentId: url.searchParams.get('paymentId') ?? undefined,
      studentId: url.searchParams.get('studentId') ?? undefined,
      docType: url.searchParams.get('docType') ?? undefined,
      academicYear: url.searchParams.get('academicYear') ?? undefined,
      termNumber: url.searchParams.get('termNumber') ?? undefined,
      limit: url.searchParams.get('limit') ?? undefined,
    })

    if (!parsed.success) {
      return fail('VALIDATION_ERROR', parsed.error.issues[0]?.message ?? 'Invalid query.')
    }

    const client = await createUserClient()
    if (!client) return fail('UNAUTHORIZED', 'Authentication required.')

    /*
      One literal `select`, never concatenated.

      PostgREST loses row-type inference when the column list is built from pieces, and
      the symptom is a `GenericStringError` that names nothing useful.
    */
    let query = client
      .from('generated_documents')
      .select(
        /*
          The pupil's name is embedded through the `student_id` foreign key rather than
          fetched per row. A report-card list of 400 showing only UUIDs is unusable, and
          the policies on `students` apply to the embed exactly as they do to a direct
          read — staff see their own school's pupils, a parent sees their own children.
        */
        'id, doc_type, status, byte_size, failure_reason, student_id, payment_id, academic_year, term_number, created_at, students(first_name, last_name)',
      )
      .order('created_at', { ascending: false })
      .limit(parsed.data.limit)

    if (parsed.data.paymentId) query = query.eq('payment_id', parsed.data.paymentId)
    if (parsed.data.studentId) query = query.eq('student_id', parsed.data.studentId)
    if (parsed.data.docType) query = query.eq('doc_type', parsed.data.docType)
    if (parsed.data.academicYear) query = query.eq('academic_year', parsed.data.academicYear)
    if (parsed.data.termNumber) query = query.eq('term_number', parsed.data.termNumber)

    const { data, error } = await query
    if (error) return fromPostgrestError(error)

    const rows = data ?? []

    return ok({
      documents: rows.map((d) => ({
        id: d.id,
        docType: d.doc_type,
        status: d.status,
        byteSize: d.byte_size,
        /*
          The reason a document failed is shown to the school, because the remedy is
          usually theirs — a pupil with no class, a term with no marks. Withholding it
          produces a support call that this field would have answered.
        */
        failureReason: d.failure_reason,
        studentId: d.student_id,
        /*
          PostgREST returns an embed as an object for a to-one relationship and an array
          when it cannot prove the cardinality. Both are handled, because getting this
          wrong produces `undefined` rather than an error and the name silently vanishes.
        */
        studentName: (() => {
          const embed = (d as { students?: unknown }).students
          const row = Array.isArray(embed) ? embed[0] : embed
          const named = row as { first_name?: string; last_name?: string } | null | undefined
          if (!named?.first_name && !named?.last_name) return null
          return `${named.first_name ?? ''} ${named.last_name ?? ''}`.trim()
        })(),
        paymentId: d.payment_id,
        academicYear: d.academic_year,
        termNumber: d.term_number,
        createdAt: d.created_at,
      })),
      meta: {
        /*
          Counted separately so a screen can say "still being produced" rather than
          "none", which are different things with different remedies.
        */
        ready: rows.filter((d) => d.status === 'ready').length,
        pending: rows.filter((d) => d.status === 'pending' || d.status === 'generating')
          .length,
        failed: rows.filter((d) => d.status === 'failed').length,
      },
    })
  })
}
